rcle","toName":"aoiAreaCircle","mustNeed":false,"type":3,"subType":5,"style":1,"description":"若aoi_type=circle，必填 单位: m 圆心+半径","cipherTextType":1,"children":[{"requestName":"location","toName":"location","mustNeed":false,"type":5,"style":1,"description":"圆心经纬度","cipherTextType":1,"children":[{"requestName":"longitude","toName":"longitude","mustNeed":true,"type":2,"style":1,"example":"111.23","description":"经度","cipherTextType":1},{"requestName":"latitude","toName":"latitude","mustNeed":true,"type":2,"style":1,"example":"111.23","description":"维度","cipherTextType":1},{"requestName":"standard","toName":"standard","mustNeed":true,"type":2,"style":1,"example":"GaoDe","description":"地图标准","cipherTextType":1}]},{"requestName":"circle_radius","toName":"circleRadius","mustNeed":true,"type":1,"style":1,"example":"10000","description":"半径","cipherTextType":1}]},{"requestName":"aoi_area_polygon_list","toName":"aoiAreaPolygonList","mustNeed":false,"type":2,"style":1,"example":"{{   经度A,纬度A;    经度B,纬度B;   经度C,纬度C; }}","description":"若aoi_category=polygon，则回传经纬度点集合 构成的电子围栏多边形的经纬度坐标(高德体系经纬度) 例如: {   经度A,纬度A;    经度B,纬度B;   经度C,纬度C; }","cipherTextType":1},{"requestName":"aoi_op_type","toName":"aoiOpType","mustNeed":true,"type":6,"style":1,"example":"{aoi_type=1,新增门店可达电子围栏} {aoi_type=2,修改门店可达电子围栏} {aoi_type=3,启用门店可达电子围栏} {aoi_type=4,停用门店可达电子围栏}","description":"变更类型","cipherTextType":1},{"requestName":"fulfill_service","toName":"fulfillService","mustNeed":false,"type":3,"subType":2,"style":1,"example":"无接触派送","description":"门店到此电子围栏的服务","cipherTextType":1}]},"response":{"responseData":[{"responseName":"return_code","fromName":"returnCode","type":2,"example":"0","description":"错误码，0 - 成功","securityLevel":"R1"},{"responseName":"message","fromName":"message","type":2,"example":"xx错了","description":"错误信息，失败时填写","securityLevel":"R1"}]},"demo":{"requestDemo":{"curl":{"reqUrl":"https://openapi-fxg.jinritemai.com/logistics/ind/aoi/push?app_key=your_appkey_here&method=logistics.ind.aoi.push&ac